import {jest} from '@jest/globals';
import {createMessageHandler} from './messageHandler.js';
import {validateMessage} from './validation.js';
import {InMemorySessionStore} from '../../infrastructure/stores/inMemorySessionStore.js';
import type {SessionSummary} from '../../types/sessionStore.js';
import {startEngineWith, connectClient, stopEngines} from '../wsTestSupport.js';
import type {IncomingMessage, OutgoingMessage} from '../../types/messages.js';

describe('Conversation List Acceptance', () => {
  const orchestrator = {
    processMessageStream: jest.fn().mockImplementation(async function* () {
      yield {type: 'stop', stopReason: 'end_turn'};
    }),
  } as any;

  afterEach(async () => {
    await stopEngines();
    jest.restoreAllMocks();
  });

  describe('Protocol Stability', () => {
    it('pins that every message literal valid before this change still compiles', () => {
      const _incoming: IncomingMessage[] = [
        {type: 'user_message', content: 'hello'},
        {type: 'ping', timestamp: 123},
      ];

      const _outgoing: OutgoingMessage[] = [
        {type: 'connected', sessionId: 's1', message: 'hi', examplePrompts: []},
        {type: 'entry_upsert', index: 0, entry: {role: 'user', content: 'hi', timestamp: '2026-01-01T00:00:00Z'}},
        {type: 'entry_delta', index: 0, delta: ' '},
        {type: 'entry_commit', index: 0},
        {type: 'entry_skip', index: 0},
        {type: 'error', code: 'ERR', message: 'msg'},
        {type: 'pong', timestamp: 123},
        {type: 'stream_end'},
      ];
      expect(true).toBe(true);
    });
  });

  describe('Protocol Validation', () => {
    it('accepts valid list_conversations frame', () => {
      const result = validateMessage({type: 'list_conversations'} as any);
      expect(result).toEqual({valid: true, data: {type: 'list_conversations'}});
    });

    it('rejects invalid limit (0)', () => {
      const result = validateMessage({type: 'list_conversations', limit: 0} as any);
      expect(result.valid).toBe(false);
      expect(result.error).toMatch(/limit/i);
    });

    it('rejects invalid limit (201)', () => {
      const result = validateMessage({type: 'list_conversations', limit: 201} as any);
      expect(result.valid).toBe(false);
      expect(result.error).toMatch(/limit/i);
    });

    it('rejects non-integer limit', () => {
      const result = validateMessage({type: 'list_conversations', limit: 1.5} as any);
      expect(result.valid).toBe(false);
      expect(result.error).toMatch(/limit/i);
    });

    it('rejects invalid before cursor', () => {
      const result = validateMessage({type: 'list_conversations', before: 'not-a-cursor'} as any);
      expect(result.valid).toBe(false);
      expect(result.error).toMatch(/before/i);
    });

    it('rejects incomplete before cursor (missing sessionId)', () => {
      const result = validateMessage({type: 'list_conversations', before: {updatedAt: '2026-01-01T00:00:00Z'}} as any);
      expect(result.valid).toBe(false);
      expect(result.error).toMatch(/before/i);
    });
  });

  describe('Delivery and Authorization', () => {
    it('delivers conversation list newest first when history is enabled', async () => {
      const store = new InMemorySessionStore();
      const s1: SessionSummary = {
        sessionId: 's1',
        createdAt: new Date('2026-01-01T00:00:00Z'),
        updatedAt: new Date('2026-01-01T02:00:00Z'),
        entryCount: 1,
      };
      const s2: SessionSummary = {
        sessionId: 's2',
        createdAt: new Date('2026-01-01T00:00:00Z'),
        updatedAt: new Date('2026-01-01T01:00:00Z'),
        entryCount: 2,
      };
      jest.spyOn(store as any, 'listFor').mockResolvedValue([s1, s2]);

      const handle = (createMessageHandler as any)(orchestrator, {sessionStore: store, history: {enabled: true}});
      const ws = {send: jest.fn(), userId: 'u1'} as any;
      const session = {sessionId: 's_current', userId: 'u1', entries: []};

      await handle(ws, session, {type: 'list_conversations'});

      expect(ws.send).toHaveBeenCalledTimes(1);
      const sent = JSON.parse(ws.send.mock.calls[0][0]);
      expect(sent).toEqual({
        type: 'conversation_list',
        conversations: [
          {
            sessionId: 's1',
            createdAt: '2026-01-01T00:00:00.000Z',
            updatedAt: '2026-01-01T02:00:00.000Z',
            entryCount: 1,
          },
          {
            sessionId: 's2',
            createdAt: '2026-01-01T00:00:00.000Z',
            updatedAt: '2026-01-01T01:00:00.000Z',
            entryCount: 2,
          },
        ],
      });
    });

    it('ignores userId in the frame and uses ws.userId instead', async () => {
      const store = new InMemorySessionStore();
      const listFor = jest.spyOn(store as any, 'listFor').mockResolvedValue([]);

      const handle = (createMessageHandler as any)(orchestrator, {sessionStore: store, history: {enabled: true}});
      const ws = {send: jest.fn(), userId: 'u_correct'} as any;
      const session = {sessionId: 's1', userId: 'u_correct', entries: []};

      await handle(ws, session, {type: 'list_conversations', userId: 'u_evil'} as any);

      expect(listFor).toHaveBeenCalledWith('u_correct', expect.anything());
    });

    it('passes limit and before cursor to listFor', async () => {
      const store = new InMemorySessionStore();
      const listFor = jest.spyOn(store as any, 'listFor').mockResolvedValue([]);

      const handle = (createMessageHandler as any)(orchestrator, {sessionStore: store, history: {enabled: true}});
      const ws = {send: jest.fn(), userId: 'u1'} as any;
      const session = {sessionId: 's1', userId: 'u1', entries: []};
      const before = {updatedAt: '2026-01-01T00:00:00Z', sessionId: 's0'};

      await handle(ws, session, {type: 'list_conversations', limit: 10, before} as any);

      expect(listFor).toHaveBeenCalledWith('u1', {limit: 10, before});
    });
  });

  describe('Feature Gating and Error Handling', () => {
    it('returns UNSUPPORTED error when history is disabled', async () => {
      const store = new InMemorySessionStore();
      const handle = (createMessageHandler as any)(orchestrator, {sessionStore: store, history: {enabled: false}});
      const ws = {send: jest.fn(), userId: 'u1'} as any;
      const session = {sessionId: 's1', userId: 'u1', entries: []};

      await handle(ws, session, {type: 'list_conversations'} as any);

      const sent = JSON.parse(ws.send.mock.calls[0][0]);
      expect(sent).toEqual({
        type: 'error',
        code: 'UNSUPPORTED',
        message: expect.any(String),
      });
    });

    it('returns UNSUPPORTED error when store does not implement listFor', async () => {
      const store = {get: jest.fn()} as any; // No listFor
      const handle = (createMessageHandler as any)(orchestrator, {sessionStore: store, history: {enabled: true}});
      const ws = {send: jest.fn(), userId: 'u1'} as any;
      const session = {sessionId: 's1', userId: 'u1', entries: []};

      await handle(ws, session, {type: 'list_conversations'} as any);

      const sent = JSON.parse(ws.send.mock.calls[0][0]);
      expect(sent.code).toBe('UNSUPPORTED');
    });

    it('returns SERVER_ERROR when listFor rejects with generic error', async () => {
      const store = new InMemorySessionStore();
      jest.spyOn(store as any, 'listFor').mockRejectedValue(new Error('DB failure'));

      const handle = (createMessageHandler as any)(orchestrator, {sessionStore: store, history: {enabled: true}});
      const ws = {send: jest.fn(), userId: 'u1'} as any;
      const session = {sessionId: 's1', userId: 'u1', entries: []};

      await handle(ws, session, {type: 'list_conversations'} as any);

      const sent = JSON.parse(ws.send.mock.calls[0][0]);
      expect(sent.code).toBe('SERVER_ERROR');
      expect(sent.message).not.toContain('DB failure');
    });

    it('returns UNSUPPORTED when listFor throws StoreCannotList', async () => {
      const store = new InMemorySessionStore();
      const error = new Error('Unsupported');
      error.name = 'StoreCannotList';
      jest.spyOn(store as any, 'listFor').mockRejectedValue(error);

      const handle = (createMessageHandler as any)(orchestrator, {sessionStore: store, history: {enabled: true}});
      const ws = {send: jest.fn(), userId: 'u1'} as any;
      const session = {sessionId: 's1', userId: 'u1', entries: []};

      await handle(ws, session, {type: 'list_conversations'} as any);

      const sent = JSON.parse(ws.send.mock.calls[0][0]);
      expect(sent.code).toBe('UNSUPPORTED');
    });
  });

  describe('Concurrency', () => {
    it('answers list_conversations immediately even while user_message is streaming', async () => {
      const store = new InMemorySessionStore();
      jest.spyOn(store as any, 'listFor').mockResolvedValue([]);

      const handle = (createMessageHandler as any)(orchestrator, {sessionStore: store, history: {enabled: true}});
      const ws = {send: jest.fn(), userId: 'u1'} as any;
      const session = {sessionId: 's1', userId: 'u1', entries: []};

      // Mock orchestrator to hang
      const {until, release} = deferred();
      orchestrator.processMessageStream.mockImplementation(async function* () {
        await until;
        yield {type: 'stop', stopReason: 'end_turn'};
      });

      const userMessagePromise = handle(ws, session, {type: 'user_message', content: 'hello'});

      // Send list_conversations while user_message is still hanging
      await handle(ws, session, {type: 'list_conversations'} as any);

      // Should have sent conversation_list already
      const sentTypes = ws.send.mock.calls.map(c => JSON.parse(c[0]).type);
      expect(sentTypes).toContain('conversation_list');
      expect(sentTypes).not.toContain('stream_end');

      release();
      await userMessagePromise;
    });
  });

  describe('End-to-end Reconnection', () => {
    it('allows reconnecting with a sessionId from a conversation_list', async () => {
      const store = new InMemorySessionStore();
      const session = store.create('s_old', 'u1');
      session.entries.push({role: 'user', content: 'hello', timestamp: new Date().toISOString()});
      session.entries.push({role: 'assistant', content: 'hi', timestamp: new Date().toISOString(), isStreaming: false});

      const {url} = await startEngineWith({
        sessionStore: store,
        history: {enabled: true},
        resume: {enabled: true},
      } as any);

      const client = connectClient(url);

      // Wait for connected frame
      await new Promise<void>(resolve => {
        client.on('message', raw => {
          if (JSON.parse(String(raw)).type === 'connected') resolve();
        });
      });

      // 1. Get list
      client.send(JSON.stringify({type: 'list_conversations'}));

      const listFrame = await new Promise<any>(resolve => {
        client.on('message', raw => {
          const frame = JSON.parse(String(raw));
          if (frame.type === 'conversation_list') resolve(frame);
        });
      });

      expect(listFrame.conversations[0].sessionId).toBe('s_old');

      // 2. Reconnect with sessionId from list
      const client2 = connectClient(`${url.split('?')[0]}?sessionId=s_old`);

      const connectedFrame = await new Promise<any>(resolve => {
        client2.on('message', raw => {
          const frame = JSON.parse(String(raw));
          if (frame.type === 'connected') resolve(frame);
        });
      });

      expect(connectedFrame.resumed).toBe(true);
      expect(connectedFrame.sessionId).toBe('s_old');
    });
  });
});

function deferred() {
  let release = () => {};
  const until = new Promise<void>(r => (release = r));
  return {until, release};
}

